function applyTheme(){let dark=prefs.theme==='dark'||(prefs.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.lang=lang;}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);applyTheme();
async function initStore(){try{db=await new Promise((resolve,reject)=>{let r=indexedDB.open('where-is-it',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});let saved=await new Promise((resolve,reject)=>{let r=db.transaction('data').objectStore('data').get('inventory');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(saved)state=validate(saved);}catch{storageAvailable=false;}}
async function commit(next){if(db&&storageAvailable){await new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(next,'inventory');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}state=next;}
async function change(mutator){const next=structuredClone(state);mutator(next);try{await commit(next);return true;}catch{toast(t('storageError'));return false;}}
const place=id=>state.places.find(p=>p.id===id), item=id=>state.items.find(p=>p.id===id);
function chain(id){let a=[],seen=new Set();while(id&&!seen.has(id)){seen.add(id);let p=place(id);if(!p)break;a.unshift(p);id=p.parent;}return a;}
function path(id){return chain(id).map(p=>p.name).join(' › ');}
function descendants(id){let ids=new Set([id]),size=-1;while(size!==ids.size){size=ids.size;state.places.forEach(p=>{if(ids.has(p.parent))ids.add(p.id);});}return ids;}
function count(id){let ids=descendants(id);return state.items.filter(i=>ids.has(i.location)).length;}
function breadcrumbs(id){return `<div class="breadcrumbs">${chain(id).map(p=>`<a href="#place/${p.id}">${esc(p.name)}</a>`).join('<span>›</span>')||esc(t('noLocation'))}</div>`;}
function itemLocationText(i){return [path(i.location),i.shelf,i.position].filter(Boolean).join(' › ');}
function itemLocationDetails(i){return i.shelf||i.position?`<p class="location-detail">${esc([i.shelf,i.position].filter(Boolean).join(' · '))}</p>`:'';}
function card(obj,isPlace=false){const location=isPlace?obj.parent:obj.location;return `<a class="card" href="#${isPlace?'place':'item'}/${obj.id}"><div class="card-visual">${obj.photo?`<img src="${esc(obj.photo)}" alt="${esc(obj.name)}" loading="lazy">`:icon(isPlace?(obj.type==='room'?'home':obj.type==='furniture'?'shelf':'box'):'box')}</div>${obj.favorite?`<span class="favorite-dot">${icon('star')}</span>`:''}<div class="card-body"><h3>${esc(obj.name)}</h3><p class="path">${esc(isPlace?(location?path(location):t(obj.type)):itemLocationText(obj))}</p><span class="badge">${isPlace?`${count(obj.id)} · ${t('items')}`:`${obj.quantity} ×${obj.category?' · '+esc(obj.category):''}`}</span></div></a>`;}
function empty(title,text,action='',label=''){return `<div class="empty">${icon('box')}<h3>${t(title)}</h3><p>${t(text)}</p>${action?`<button class="button" data-action="${action}">${t(label)}</button>`:''}</div>`;}
function collection(arr,isPlace=false){return `<div class="${prefs.view==='list'?'list':'grid'}">${arr.map(x=>card(x,isPlace)).join('')}</div>`;}
function searchbox(value=''){return `<label class="searchbox">${icon('search')}<input id="searchInput" type="search" autocomplete="off" placeholder="${t('searchHint')}" aria-label="${t('search')}" value="${esc(value)}"></label>`;}
function render(){
 document.title=`${t('brand')} · ${t(current.page==='place'?'places':current.page==='item'?'items':current.page)}`;
 $('#brand').textContent=t('brand');$('#settingsButton').innerHTML=icon('settings');$('#settingsButton').ariaLabel=t('settings');$('#addButton').ariaLabel=t('add');$('#navigation').ariaLabel=t('home');
 $('#navigation').innerHTML=['home','places','search','items','favorites','shopping'].map(k=>`<a href="#${k}" class="nav-link ${current.page===k||(k==='places'&&current.page==='place')||(k==='items'&&current.page==='item')?'active':''}" ${current.page===k?'aria-current="page"':''}>${icon({places:'shelf',items:'box',favorites:'star',shopping:'cart'}[k]||k)}<span>${t(k==='shopping'?'shoppingNav':k)}</span></a>`).join('');
 const pages={home:renderHome,places:renderPlaces,items:renderItems,search:renderSearch,favorites:renderFavorites,settings:renderSettings,shopping:renderShopping,place:renderPlace,item:renderItem};
 $('#main').innerHTML=(!storageAvailable?`<div class="banner" role="alert">${t('unavailable')}</div>`:'')+(pages[current.page]||renderHome)();bindPage();
}
function renderHome(){const roots=state.places.filter(p=>!p.parent),recent=[...state.items].sort((a,b)=>b.created-a.created).slice(0,4);return `<p class="eyebrow">${t('eyebrow')}</p><h1>${t('greeting')}</h1><p class="intro">${t('subtitle')}</p>${searchbox()}<div class="hero"><div class="hero-text"><p class="eyebrow">${t('brand')}</p><h2>${t('heroTitle')}</h2><p>${t('heroText')}</p></div><div class="hero-art"><svg viewBox="0 0 160 170" fill="none" aria-hidden="true"><rect x="24" y="14" width="103" height="137" rx="12" fill="#287a56"/><rect x="32" y="23" width="87" height="119" rx="7" fill="#f3ecd9"/><path d="M32 64h87M32 104h87" stroke="#287a56" stroke-width="5"/><rect x="43" y="35" width="21" height="27" rx="3" fill="#e9bb70"/><rect x="70" y="31" width="10" height="31" rx="2" fill="#79a78c"/><rect x="85" y="38" width="22" height="24" rx="4" fill="#c48d68"/><rect x="43" y="76" width="63" height="25" rx="5" fill="#a2b998"/><path d="M64 84h21" stroke="#f3ecd9" stroke-width="3" stroke-linecap="round"/><rect x="44" y="117" width="25" height="23" rx="4" fill="#c48d68"/><rect x="76" y="114" width="29" height="26" rx="4" fill="#e9bb70"/><path d="M37 151v8M114 151v8" stroke="#287a56" stroke-width="8" stroke-linecap="round"/><circle cx="130" cy="37" r="21" fill="#e9bb70"/><path d="m121 37 6 6 12-13" stroke="#287a56" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg></div></div><div class="stats"><div class="stat"><strong>${state.items.length}</strong><span>${t('items')}</span></div><div class="stat"><strong>${state.places.length}</strong><span>${t('places')}</span></div><div class="stat"><strong>${state.items.filter(i=>i.favorite).length+state.places.filter(i=>i.favorite).length}</strong><span>${t('favorites')}</span></div></div><div class="section-head"><h2>${t('yourPlaces')}</h2><a href="#places">${t('all')} →</a></div>${roots.length?collection(roots.slice(0,4),true):empty('emptyPlaces','emptyPlacesText','new-place','createPlace')}<div class="section-head"><h2>${t('recent')}</h2><a href="#items">${t('all')} →</a></div>${recent.length?collection(recent):empty('emptyItems','emptyItemsText','new-item','addItem')}${!state.items.length&&!state.places.length?`<button class="demo-link" data-action="demo">${t('demo')}</button>`:''}<p class="footer-note">${t('private')}</p>`;}
function renderShopping(){
 const pending=state.shopping.filter(x=>!x.done).sort((a,b)=>a.created-b.created),bought=state.shopping.filter(x=>x.done).sort((a,b)=>(a.doneAt||0)-(b.doneAt||0));
 return `<div class="page-head"><h1>${t('shopping')}</h1><span class="shopping-count">${pending.length}</span></div><p class="intro">${t('shoppingHelp')}</p>${!state.shopping.length?empty('shoppingEmpty','shoppingEmptyHelp','new-shopping','addPurchase'):''}${pending.length?`<div class="shopping-list" aria-label="${t('toBuy')}">${pending.map(shoppingRow).join('')}</div>`:''}${bought.length?`<div class="section-head"><h2>${t('bought')} <span class="muted">· ${bought.length}</span></h2></div><div class="shopping-list" aria-label="${t('bought')}">${bought.map(shoppingRow).join('')}</div>`:''}`;
}
function shoppingRow(x){
 return `<div class="shopping-row ${x.done?'is-bought':''}" data-shopping-id="${x.id}"><button class="shopping-toggle" data-action="toggle-shopping" data-id="${x.id}" aria-pressed="${x.done}" aria-label="${esc(t(x.done?'markNeeded':'markBought')+': '+x.name)}"><span class="shopping-check">${x.done?icon('check'):''}</span><span class="shopping-text"><span class="shopping-name">${esc(x.name)}</span>${x.quantity?`<span class="shopping-quantity">${esc(x.quantity)}</span>`:''}${x.description?`<span class="shopping-description">${esc(x.description)}</span>`:''}</span></button><button class="shopping-delete" data-action="delete-shopping" data-id="${x.id}" aria-label="${esc(t('delete')+': '+x.name)}">${icon('close')}</button></div>`;
}
function shoppingForm(){
 modal(t('addPurchase'),`<form id="shoppingForm">${field('name','purchaseName','',`required maxlength="150" placeholder="${t('purchaseExample')}" autofocus`)}<details class="extra-fields"><summary>${t('moreDetails')}<span>${t('optional')}</span></summary>${field('quantity','quantity','',`maxlength="80" placeholder="${t('purchaseQuantityExample')}"`)}<label class="field">${t('purchaseDescription')}<textarea name="description" maxlength="3000" placeholder="${t('purchaseDescriptionExample')}"></textarea></label></details><div class="actions"><button class="button" type="submit">${t('add')}</button><button class="button secondary" type="button" data-action="close">${t('cancel')}</button></div></form>`);
 $('#shoppingForm').addEventListener('submit',async e=>{
  e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name){e.target.elements.name.focus();return;}setBusy(true);
  const record={id:uid(),name,quantity:f.get('quantity').trim(),description:f.get('description').trim(),done:false,created:Date.now(),doneAt:null};
  if(await change(s=>s.shopping.push(record))){closeModal();if(current.page!=='shopping')location.hash='shopping';render();toast(t('added'));}else setBusy(false);
 });
}
let shoppingBusy=false;
async function shoppingAction(id,remove=false){
 if(shoppingBusy||!state.shopping.some(x=>x.id===id))return;shoppingBusy=true;
 $('#main').querySelectorAll('.shopping-row button').forEach(b=>b.disabled=true);
 try{
  const ok=await change(s=>{if(remove)s.shopping=s.shopping.filter(x=>x.id!==id);else{const x=s.shopping.find(x=>x.id===id);x.done=!x.done;x.doneAt=x.done?Date.now():null;}});
  if(ok){render();if(remove)toast(t('deleted'));else{const button=$(`.shopping-toggle[data-id="${id}"]`);button?.focus({preventScroll:true});}}
 }finally{shoppingBusy=false;$('#main').querySelectorAll('.shopping-row button').forEach(b=>b.disabled=false);}
}

function renderPlaces(){let roots=state.places.filter(p=>!p.parent);return `<div class="page-head"><h1>${t('yourPlaces')}</h1><button class="icon-button" data-action="view" aria-label="${t(prefs.view==='grid'?'list':'grid')}">${icon('shelf')}</button></div><p class="intro">${t('emptyPlacesText')}</p>${roots.length?collection(roots,true):empty('emptyPlaces','emptyPlacesText','new-place','createPlace')}`;}
function placeOptions(selected='',exclude=new Set(),none=true){return `${none?`<option value="">${t('noParent')}</option>`:''}`+state.places.filter(p=>!exclude.has(p.id)).sort((a,b)=>path(a.id).localeCompare(path(b.id),lang)).map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(path(p.id))}</option>`).join('');}
function toolbar(){return `<div class="toolbar"><select id="placeFilter" aria-label="${t('places')}"><option value="">${t('allPlaces')}</option>${placeOptions(filters.place,new Set(),false)}</select><select id="categoryFilter" aria-label="${t('category')}"><option value="">${t('allCategories')}</option>${[...new Set(state.items.map(i=>i.category).filter(Boolean))].sort().map(c=>`<option ${c===filters.category?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}</select><select id="photoFilter" aria-label="${t('photo')}">${['anyPhoto','withPhoto','noPhoto'].map((k,n)=>`<option value="${n||''}" ${String(n||'')===filters.photo?'selected':''}>${t(k)}</option>`).join('')}</select><select id="sortFilter" aria-label="${t('allItems')}">${['newest','alphabetical','updated'].map(k=>`<option value="${k}" ${filters.sort===k?'selected':''}>${t(k)}</option>`).join('')}</select></div>`;}
function filteredItems(query=''){const q=normalize(query),ids=filters.place?descendants(filters.place):null;let a=state.items.filter(i=>(!ids||ids.has(i.location))&&(!filters.category||i.category===filters.category)&&(!filters.photo||(filters.photo==='1'?!!i.photo:!i.photo))&&(!q||normalize([i.name,i.description,i.tags,i.aliases,i.category,i.shelf,i.position,path(i.location)].join(' ')).includes(q)));a.sort(filters.sort==='alphabetical'?(a,b)=>a.name.localeCompare(b.name,lang):filters.sort==='updated'?(a,b)=>b.updated-a.updated:(a,b)=>b.created-a.created);return a;}
function normalize(x){return String(x||'').toLocaleLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[’'`]/g,'').trim();}
function renderItems(){let a=filteredItems();return `<div class="page-head"><h1>${t('allItems')}</h1><button class="icon-button" data-action="view" aria-label="${t(prefs.view==='grid'?'list':'grid')}">${icon('shelf')}</button></div>${toolbar()}${a.length?collection(a):empty(state.items.length?'noResults':'emptyItems',state.items.length?'tryAgain':'emptyItemsText','new-item','addItem')}`;}
function results(){if(!searchQuery.trim())return empty('searchStart','searchText');const q=normalize(searchQuery),ps=state.places.filter(p=>normalize(p.name+' '+p.description+' '+path(p.parent)).includes(q)&&(!filters.place||descendants(filters.place).has(p.id))),its=filteredItems(searchQuery);return !ps.length&&!its.length?empty('noResults','tryAgain'):`<p class="result-label">${t('resultCount')}: ${ps.length+its.length}</p>${ps.length?`<div class="section-head"><h2>${t('places')}</h2></div>${collection(ps,true)}`:''}${its.length?`<div class="section-head"><h2>${t('items')}</h2></div>${collection(its)}`:''}`;}
function renderSearch(){return `<h1>${t('search')}</h1><p class="intro">${t('searchText')}</p>${searchbox(searchQuery)}${toolbar()}<div id="results" class="search-results">${results()}</div>`;}
function renderFavorites(){let ps=state.places.filter(x=>x.favorite),its=state.items.filter(x=>x.favorite);return `<h1>${t('favorites')}</h1><p class="intro">${t('favoriteText')}</p>${!ps.length&&!its.length?empty('favoriteEmpty','favoriteText'):''}${ps.length?`<div class="section-head"><h2>${t('places')}</h2></div>${collection(ps,true)}`:''}${its.length?`<div class="section-head"><h2>${t('items')}</h2></div>${collection(its)}`:''}`;}
function renderPlace(){const p=place(current.id);if(!p)return `<a class="back" href="#places">${icon('arrow')}${t('back')}</a>${empty('noMatchPlace','emptyPlacesText')}`;const children=state.places.filter(x=>x.parent===p.id).sort((a,b)=>(a.order||0)-(b.order||0)),ids=deep?descendants(p.id):new Set([p.id]),its=state.items.filter(i=>ids.has(i.location));return `<a class="back" href="#${p.parent?'place/'+p.parent:'places'}">${icon('arrow')}${t('back')}</a><p class="eyebrow">${t(p.type)}</p><div class="page-head"><h1>${esc(p.name)}</h1><button class="icon-button" data-action="favorite" data-kind="places" data-id="${p.id}" aria-label="${t(p.favorite?'unfavorite':'favorite')}" aria-pressed="${!!p.favorite}">${icon('star')}</button></div>${breadcrumbs(p.id)}${p.photo?`<img class="detail-photo" src="${esc(p.photo)}" alt="${esc(p.name)}">`:''}${p.description?`<p class="note">${esc(p.description)}</p>`:''}<div class="actions"><button class="button secondary" data-action="edit-place" data-id="${p.id}">${icon('edit')}${t('edit')}</button><button class="button secondary" data-action="new-item" data-id="${p.id}">${t('addItem')}</button><button class="button secondary" data-action="child" data-id="${p.id}">+ ${t('compartment')}</button></div>${children.length?`<div class="section-head"><h2>${t('subplaces')}</h2><button class="text-button" data-action="reorder" data-id="${p.id}">${t('reorder')}</button></div>${collection(children,true)}`:''}<div class="section-head"><h2>${t('contents')} · ${its.length}</h2></div><div class="chips"><button class="chip ${!deep?'active':''}" data-action="direct">${t('direct')}</button><button class="chip ${deep?'active':''}" data-action="deep">${t('everything')}</button></div>${its.length?collection(its):empty('emptyItems','emptyItemsText','new-item','addItem')}<div class="actions"><button class="text-button" style="color:var(--danger)" data-action="delete-place" data-id="${p.id}">${t('delete')}</button></div>`;}
function renderItem(){const i=item(current.id);if(!i)return `<a href="#items" class="back">${t('back')}</a>`;return `<a class="back" href="#${i.location?'place/'+i.location:'items'}">${icon('arrow')}${t('back')}</a><div class="page-head"><h1>${esc(i.name)}</h1><button class="icon-button" data-action="favorite" data-kind="items" data-id="${i.id}" aria-label="${t(i.favorite?'unfavorite':'favorite')}" aria-pressed="${!!i.favorite}">${icon('star')}</button></div>${i.photo?`<img class="detail-photo" src="${esc(i.photo)}" alt="${esc(i.name)}">`:`<div class="detail-placeholder">${icon('box')}</div>`}<div class="location-panel"><p class="eyebrow">${t('where')}</p>${breadcrumbs(i.location)}${itemLocationDetails(i)}</div><div class="actions"><button class="button" data-action="move" data-id="${i.id}">${icon('pin')}${t('move')}</button><button class="button secondary" data-action="edit-item" data-id="${i.id}">${icon('edit')}${t('edit')}</button><button class="button secondary" data-action="duplicate" data-id="${i.id}">${t('duplicate')}</button></div><div class="detail-info"><div><span class="muted">${t('quantity')}</span><strong>${i.quantity}</strong></div>${i.category?`<div><span class="muted">${t('category')}</span><strong>${esc(i.category)}</strong></div>`:''}</div>${i.tags?`<div class="chips">${i.tags.split(',').filter(x=>x.trim()).map(x=>`<span class="badge">${esc(x.trim())}</span>`).join('')}</div>`:''}${i.description?`<div class="section-head"><h2>${t('description')}</h2></div><p class="note">${esc(i.description)}</p>`:''}${i.locationPhoto?`<div class="section-head"><h2>${t('locationPhoto')}</h2></div><img class="detail-photo" src="${esc(i.locationPhoto)}" alt="${t('locationPhoto')}">`:''}${i.aliases?`<p class="help">${t('aliases')}: ${esc(i.aliases)}</p>`:''}<div class="actions"><button class="text-button" style="color:var(--danger)" data-action="delete-item" data-id="${i.id}">${t('delete')}</button></div>`;}
function renderSettings(){return `<h1>${t('settings')}</h1><p class="intro">${t('about')}</p><div class="settings-grid"><section class="settings-section"><h2>${t('language')}</h2><label class="field">${t('language')}<select id="language">${[['uk','Українська'],['en','English'],['ru','Русский']].map(([v,n])=>`<option value="${v}" ${lang===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">${t('theme')}<select id="theme">${['system','light','dark'].map(v=>`<option value="${v}" ${prefs.theme===v?'selected':''}>${t(v)}</option>`).join('')}</select></label></section><section class="settings-section"><h2>${t('data')}</h2><p>${t('localInfo')}</p><button class="button" data-action="export">${icon('download')}${t('export')}</button><button class="button secondary" data-action="import">${t('import')}</button><input id="importFile" type="file" accept="application/json,.json" class="hidden"><p class="help">${t('lastBackup')}: ${prefs.lastBackup?new Date(prefs.lastBackup).toLocaleString(lang):t('never')}</p>${state.places.some(p=>p.demo)?`<button class="text-button" data-action="remove-demo">${t('removeDemo')}</button><br>`:''}<button class="text-button" style="color:var(--danger)" data-action="clear">${t('clear')}</button></section></div><section class="settings-section"><img src="logo.svg" alt="" width="50" height="50"><h2 style="margin-top:12px">${t('brand')}</h2><p>${t('aboutText')}</p><span class="help">${t('version')}</span><p class="help" style="margin-top:15px">${t('reloadHelp')}</p><button class="button secondary" data-action="reload-app">${t('reloadApp')}</button></section>`;}
function bindPage(){
 $('#searchInput')?.addEventListener('input',e=>{searchQuery=e.target.value;if(current.page!=='search'){location.hash='search';}else $('#results').innerHTML=results();});
 for(const [id,key] of [['placeFilter','place'],['categoryFilter','category'],['photoFilter','photo'],['sortFilter','sort']])$('#'+id)?.addEventListener('change',e=>{filters[key]=e.target.value;render();});
 $('#language')?.addEventListener('change',e=>{lang=e.target.value;prefs.lang=lang;savePrefs();render();});$('#theme')?.addEventListener('change',e=>{prefs.theme=e.target.value;savePrefs();});
 $('#importFile')?.addEventListener('change',e=>{let file=e.target.files[0];if(file)readBackup(file);e.target.value='';});
}
function modal(title,body){$('#modalContent').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function addMenu(){modal(t('addTitle'),`<button class="add-option" data-action="new-place">${icon('shelf')}<span>${t('createPlace')}<small>${t('placeAddHint')}</small></span></button><button class="add-option" data-action="new-item">${icon('box')}<span>${t('addItem')}<small>${t('itemHint')}</small></span></button>`);}
let formPhotos={},pendingPhotos=0,photoSession=0;
function photoField(key,title,value){return `<div class="photo-control"><label class="field">${t(title)}<input type="file" accept="image/jpeg,image/png,image/webp" data-photo="${key}"></label><div id="preview-${key}">${value?`<img class="photo-preview" src="${esc(value)}" alt="${t(title)}"><button type="button" class="text-button" data-action="remove-photo" data-key="${key}">${t('removePhoto')}</button>`:''}</div></div>`;}
function field(key,title,value='',extra=''){return `<label class="field">${t(title)}<input name="${key}" value="${esc(value)}" ${extra}></label>`;}
function setupFormPhotos(values){formPhotos={...values};pendingPhotos=0;photoSession++;}
function placeForm(id=null,type='furniture',parent=null){
 const p=place(id),excluded=p?descendants(p.id):new Set();
 setupFormPhotos({photo:p?.photo||''});
 modal(t(p?'edit':'createPlace'),`<form id="placeForm">
 ${field('name','placeName',p?.name||'',`required maxlength="150" placeholder="${t('placeExample')}" autofocus`)}
 <p class="help">${t('placeSimpleHelp')}</p>
 <details class="extra-fields"><summary>${t('moreDetails')}<span>${t('optional')}</span></summary>
 <label class="field">${t('description')}<textarea name="description" maxlength="3000" placeholder="${t('placeDescriptionExample')}">${esc(p?.description||'')}</textarea></label>
 ${photoField('photo','photo',p?.photo)}<p class="help">${t('photoHelp')}</p>
 <label class="field">${t('parent')}<select name="parent">${placeOptions(p?.parent||parent||'',excluded)}</select><small>${t('roomHint')}</small></label>
 <label class="field">${t('type')}<select name="type">${['furniture','compartment','room'].map(k=>`<option value="${k}" ${(p?.type||type)===k?'selected':''}>${t(k)}</option>`).join('')}</select></label>
 <label class="check"><input type="checkbox" name="favorite" ${p?.favorite?'checked':''}>${t('favorite')}</label>
 </details>
 <div class="actions"><button class="button" type="submit">${t('save')}</button><button class="button secondary" type="button" data-action="close">${t('cancel')}</button></div></form>`);
 $('#placeForm').addEventListener('submit',async e=>{
  e.preventDefault();if(pendingPhotos)return;let f=new FormData(e.target),name=f.get('name').trim();if(!name){e.target.elements.name.focus();return;}
  const data={...p,id:p?.id||uid(),name,type:f.get('type'),parent:f.get('parent')||null,description:f.get('description').trim(),photo:formPhotos.photo,favorite:f.has('favorite'),created:p?.created||Date.now(),updated:Date.now(),order:p?.order??Date.now()};
  setBusy(true);let ok=await change(s=>{if(p)s.places[s.places.findIndex(x=>x.id===p.id)]=data;else s.places.push(data);});
  if(ok){closeModal();location.hash='place/'+data.id;render();toast(t('saved'));}else setBusy(false);
 });
}
function locationPicker(selected=''){
 const isNew=!selected&&!state.places.length;
 return `<label class="field">${t('placeLabel')}<select name="location" id="itemLocation" required>
 ${!isNew?`<option value="">${t('choosePlace')}</option>`:''}${placeOptions(selected,new Set(),false)}
 <option value="__new" ${isNew?'selected':''}>＋ ${t('newPlace')}</option></select></label>
 <div id="newPlaceFields" ${isNew?'':'class="hidden"'}>${field('newPlaceName','placeName','',`maxlength="150" placeholder="${t('placeExample')}" ${isNew?'required':''}`)}<p class="help">${t('newPlaceHelp')}</p></div>`;
}
function bindLocationPicker(){
 $('#itemLocation').addEventListener('change',e=>{
  const isNew=e.target.value==='__new';$('#newPlaceFields').classList.toggle('hidden',!isNew);
  const input=$('[name="newPlaceName"]');input.required=isNew;input.disabled=!isNew;if(isNew)input.focus();
 });
 $('[name="newPlaceName"]').disabled=$('#itemLocation').value!=='__new';
}
function resolveLocation(f){
 let loc=f.get('location');if(loc!=='__new')return place(loc)?{id:loc,newPlace:null}:null;
 const name=String(f.get('newPlaceName')||'').trim();if(!name)return null;
 const existing=state.places.find(p=>!p.parent&&normalize(p.name)===normalize(name));
 if(existing)return {id:existing.id,newPlace:null};
 const p={id:uid(),name,type:'furniture',parent:null,description:'',photo:'',favorite:false,created:Date.now(),updated:Date.now(),order:Date.now()};
 return {id:p.id,newPlace:p};
}
function optionalLocationFields(i={}){return `${field('shelf','shelfLabel',i.shelf||'',`maxlength="200" placeholder="${t('shelfExample')}"`)}${field('position','exactPosition',i.position||'',`maxlength="300" placeholder="${t('positionExample')}"`)}`;}
function itemForm(id=null,locationId=null,duplicate=false){
 const i=item(id);setupFormPhotos({photo:i?.photo||'',locationPhoto:i?.locationPhoto||''});
 modal(t(i&&!duplicate?'edit':'addItem'),`<form id="itemForm">
 ${field('name','itemName',i?i.name+(duplicate?' · '+t('copy'):''):'',`required maxlength="150" placeholder="${t('itemExample')}" autofocus`)}
 ${locationPicker(i?.location||locationId||'')}
 ${photoField('photo','itemPhoto',i?.photo)}
 <details class="extra-fields"><summary>${t('moreDetails')}<span>${t('optional')}</span></summary>
 <p class="help">${t('detailsHelp')}</p>${optionalLocationFields(i||{})}
 <label class="field">${t('description')}<textarea name="description" maxlength="3000" placeholder="${t('descriptionExample')}">${esc(i?.description||'')}</textarea></label>
 ${photoField('locationPhoto','locationPhoto',i?.locationPhoto)}<p class="help">${t('photoHelp')}</p>
 <div class="row">${field('quantity','quantity',i?.quantity??1,'type="number" required min="1" max="999999" step="1"')}${field('category','category',i?.category||'','maxlength="100" list="categoryNames"')}</div>
 <datalist id="categoryNames">${[...new Set(state.items.map(x=>x.category).filter(Boolean))].map(x=>`<option value="${esc(x)}">`).join('')}</datalist>
 ${field('tags','tags',i?.tags||'','maxlength="500"')}${field('aliases','aliases',i?.aliases||'','maxlength="500"')}
 <label class="check"><input type="checkbox" name="favorite" ${i?.favorite?'checked':''}>${t('favorite')}</label></details>
 <div class="actions"><button class="button" type="submit" name="mode" value="save">${t('save')}</button><button class="button secondary" type="submit" name="mode" value="another">${t('saveAnother')}</button></div></form>`);
 bindLocationPicker();
 $('#itemForm').addEventListener('submit',async e=>{
  e.preventDefault();if(pendingPhotos)return;const f=new FormData(e.target),name=f.get('name').trim(),resolved=resolveLocation(f);
  if(!name){e.target.elements.name.focus();return;}if(!resolved){$('[name="newPlaceName"]').focus();return;}
  const old=i&&!duplicate?i:null,data={...old,id:old?.id||uid(),name,location:resolved.id,shelf:f.get('shelf').trim(),position:f.get('position').trim(),quantity:Number(f.get('quantity')),category:f.get('category').trim(),tags:f.get('tags').trim(),aliases:f.get('aliases').trim(),description:f.get('description').trim(),favorite:f.has('favorite'),photo:formPhotos.photo,locationPhoto:formPhotos.locationPhoto,created:old?.created||Date.now(),updated:Date.now()};
  setBusy(true);let ok=await change(s=>{if(resolved.newPlace)s.places.push(resolved.newPlace);if(old)s.items[s.items.findIndex(x=>x.id===old.id)]=data;else s.items.push(data);});
  if(ok){toast(t('saved'));if(e.submitter?.value==='another')itemForm(null,resolved.id);else{closeModal();location.hash='item/'+data.id;render();}}else setBusy(false);
 });
}

function setBusy(b){$('#modal').querySelectorAll('button[type="submit"]').forEach(el=>el.disabled=b);}
async function compressPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20*1024*1024)throw Error('photo');let url=URL.createObjectURL(file);try{let im=await new Promise((res,rej)=>{let img=new Image();img.onload=()=>res(img);img.onerror=rej;img.src=url;});let scale=Math.min(1,1400/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*scale));c.height=Math.max(1,Math.round(im.height*scale));let ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.82);}finally{URL.revokeObjectURL(url);}}
$('#modal').addEventListener('change',async e=>{if(!e.target.dataset.photo)return;let key=e.target.dataset.photo,file=e.target.files[0],session=photoSession;if(!file)return;pendingPhotos++;setBusy(true);try{let result=await compressPhoto(file);if(session!==photoSession)return;formPhotos[key]=result;$('#preview-'+key).innerHTML=`<img class="photo-preview" src="${result}" alt="${t('photo')}"><button class="text-button" type="button" data-action="remove-photo" data-key="${key}">${t('removePhoto')}</button>`;}catch{toast(t('photoError'));}finally{if(session===photoSession){pendingPhotos--;setBusy(pendingPhotos>0);}}});
function confirmModal(title,message,action){modal(title,`<p style="margin:18px 0">${esc(message)}</p><div class="actions"><button class="button danger" id="confirmAction">${t('confirm')}</button><button class="button secondary" data-action="close">${t('cancel')}</button></div>`);$('#confirmAction').onclick=async()=>{const b=$('#confirmAction');b.disabled=true;try{await action();}catch{toast(t('storageError'));b.disabled=false;}};}
async function deleteRecord(kind,id){let obj=kind==='items'?item(id):place(id);if(!obj)return;confirmModal(t('delete')+' · '+obj.name,t(kind==='items'?'deleteConfirm':'deletePlaceConfirm'),async()=>{const snapshot=structuredClone(state),ids=kind==='places'?descendants(id):new Set();if(await change(s=>{if(kind==='items')s.items=s.items.filter(x=>x.id!==id);else{s.places=s.places.filter(x=>!ids.has(x.id));s.items=s.items.filter(x=>!ids.has(x.location));}})){deletedSnapshot=snapshot;closeModal();location.hash=kind==='items'?'items':'places';render();modal(t('deleted'),`<div class="actions"><button class="button" data-action="undo">${t('undo')}</button><button class="button secondary" data-action="close">${t('close')}</button></div>`);}});}
function moveForm(id){const i=item(id);if(!i)return;modal(t('move')+' · '+i.name,`<form id="moveForm">${locationPicker(i.location)}<p class="help">${t('moveHelp')}</p>${optionalLocationFields(i)}<button type="submit" class="button">${t('move')}</button></form>`);bindLocationPicker();$('#moveForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),resolved=resolveLocation(f);if(!resolved)return;setBusy(true);if(await change(s=>{if(resolved.newPlace)s.places.push(resolved.newPlace);let x=s.items.find(x=>x.id===id);x.location=resolved.id;x.shelf=f.get('shelf').trim();x.position=f.get('position').trim();x.updated=Date.now();})){closeModal();render();toast(t('saved'));}else setBusy(false);};}
function reorderForm(id){let children=state.places.filter(x=>x.parent===id).sort((a,b)=>(a.order||0)-(b.order||0));modal(t('reorder'),children.map((p,n)=>`<div class="section-head"><span>${esc(p.name)}</span><span><button class="icon-button" data-action="reorder-up" data-id="${p.id}" ${n===0?'disabled':''} aria-label="${t('up')}">↑</button> <button class="icon-button" data-action="reorder-down" data-id="${p.id}" ${n===children.length-1?'disabled':''} aria-label="${t('down')}">↓</button></span></div>`).join(''));}
async function reorder(id,direction){let p=place(id),arr=state.places.filter(x=>x.parent===p.parent).sort((a,b)=>(a.order||0)-(b.order||0)),index=arr.findIndex(x=>x.id===id),other=index+direction;if(other<0||other>=arr.length)return;[arr[index],arr[other]]=[arr[other],arr[index]];if(await change(s=>arr.forEach((x,n)=>s.places.find(y=>y.id===x.id).order=n))){render();reorderForm(p.parent);}}
function exportBackup(){let payload={application:'where-is-it',version:1,exported:new Date().toISOString(),data:state},blob=new Blob([JSON.stringify(payload)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='where-is-it-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);prefs.lastBackup=new Date().toISOString();savePrefs();render();}
function validate(data){
 if(!data||!Array.isArray(data.places)||!Array.isArray(data.items)||data.places.length>10000||data.items.length>50000)throw Error('data');
 const shopping=data.shopping===undefined?[]:data.shopping;if(!Array.isArray(shopping)||shopping.length>50000)throw Error('shopping');
 const ids=new Set(),pids=new Set();const validPhoto=x=>!x||(typeof x==='string'&&x.length<=12000000&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(x));
 const text=(x,max=3000)=>typeof x==='string'&&x.length<=max;
 for(const x of [...data.places,...data.items]){if(!x||!text(x.id,100)||!x.id||!/^[\w-]+$/.test(x.id)||ids.has(x.id)||!text(x.name,150)||!x.name.trim()||!validPhoto(x.photo)||!validPhoto(x.locationPhoto))throw Error('record');ids.add(x.id);for(const k of ['description','tags','aliases','category','shelf','position'])if(x[k]!==undefined&&!text(x[k]))throw Error('text');if(x.created!==undefined&&!Number.isFinite(x.created)||x.updated!==undefined&&!Number.isFinite(x.updated))throw Error('date');}
 for(const p of data.places){if(!['room','furniture','compartment'].includes(p.type))throw Error('type');pids.add(p.id);}
 for(const p of data.places){if(p.parent&&!pids.has(p.parent))throw Error('parent');const seen=new Set([p.id]);let parent=p.parent;while(parent){if(seen.has(parent))throw Error('cycle');seen.add(parent);parent=data.places.find(x=>x.id===parent)?.parent;}}
 for(const i of data.items)if(!pids.has(i.location)||!Number.isInteger(i.quantity)||i.quantity<1||i.quantity>999999)throw Error('item');
 for(const x of shopping){if(!x||!text(x.id,100)||!x.id||!/^[\w-]+$/.test(x.id)||ids.has(x.id)||!text(x.name,150)||!x.name.trim()||!text(x.quantity,80)||!text(x.description)||typeof x.done!=='boolean'||!Number.isFinite(x.created)||(x.doneAt!==null&&!Number.isFinite(x.doneAt)))throw Error('shopping record');ids.add(x.id);}
 return {shopping:shopping.map(x=>({...x})),places:data.places.map(p=>({...p,favorite:!!p.favorite,created:p.created||0,updated:p.updated||0})),items:data.items.map(i=>({...i,favorite:!!i.favorite,created:i.created||0,updated:i.updated||0}))};
}
async function readBackup(file){try{if(file.size>200*1024*1024)throw Error('size');const payload=JSON.parse(await file.text());if(payload.application!=='where-is-it'||payload.version!==1)throw Error('format');const data=validate(payload.data);confirmModal(t('restore'),t('restoreConfirm'),async()=>{await commit(data);closeModal();filters={place:'',category:'',photo:'',sort:'newest'};render();toast(t('restored'));});}catch{toast(t('invalidFile'));}}
async function addDemo(){if(state.places.length||state.items.length)return;let r=uid(),f=uid(),s1=uid(),s2=uid(),s3=uid(),b=uid(),now=Date.now();let ok=await change(s=>{const common={photo:'',description:'',favorite:false,created:now,updated:now,demo:true};s.places.push({...common,id:r,name:t('sampleRoom'),type:'room',parent:null},{...common,id:f,name:t('sampleWardrobe'),type:'furniture',parent:r,favorite:true},...['topShelf','middleShelf','bottomShelf'].map((n,k)=>({...common,id:[s1,s2,s3][k],name:t(n),type:'compartment',parent:f,order:k})),{...common,id:b,name:t('sampleBox'),type:'compartment',parent:s2});s.items.push({...common,id:uid(),name:t('sampleItem'),location:b,quantity:2,category:'',tags:'',aliases:'',locationPhoto:'',description:t('sampleNote'),favorite:true});});if(ok){render();toast(t('demoNotice'));}}
async function action(e){const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;switch(a){
 case 'new-shopping':shoppingForm();break;case 'toggle-shopping':await shoppingAction(id);break;case 'delete-shopping':await shoppingAction(id,true);break;case 'reload-app':location.reload();break;case 'close':closeModal();break;case 'new-place':case 'add-furniture':placeForm(null,'furniture');break;case 'add-room':placeForm(null,'room');break;case 'add-compartment':placeForm(null,'compartment',current.page==='place'?current.id:null);break;case 'child':placeForm(null,'compartment',id);break;case 'new-item':case 'add-item':itemForm(null,id||(current.page==='place'?current.id:null));break;case 'edit-place':placeForm(id);break;case 'edit-item':itemForm(id);break;case 'duplicate':itemForm(id,null,true);break;case 'move':moveForm(id);break;
 case 'favorite':if(await change(s=>{let x=s[el.dataset.kind].find(x=>x.id===id);x.favorite=!x.favorite;x.updated=Date.now();}))render();break;
 case 'delete-item':deleteRecord('items',id);break;case 'delete-place':deleteRecord('places',id);break;
 case 'undo':if(deletedSnapshot){try{await commit(deletedSnapshot);deletedSnapshot=null;closeModal();render();toast(t('restored'));}catch{toast(t('storageError'));}}break;
 case 'view':prefs.view=prefs.view==='grid'?'list':'grid';savePrefs();render();break;case 'direct':deep=false;render();break;case 'deep':deep=true;render();break;
 case 'remove-photo':formPhotos[el.dataset.key]='';$('#preview-'+el.dataset.key).innerHTML='';break;
 case 'export':exportBackup();break;case 'import':$('#importFile').click();break;
 case 'clear':confirmModal(t('clear'),t('clearConfirm'),async()=>{await commit({places:[],items:[],shopping:[]});closeModal();filters={place:'',category:'',photo:'',sort:'newest'};render();toast(t('deleted'));});break;
 case 'demo':await addDemo();break;
 case 'remove-demo':{const demoPlaces=state.places.filter(x=>x.demo).length,demoItems=state.items.filter(x=>x.demo).length;confirmModal(t('removeDemo'),`${t('deletePlaceConfirm')} (${demoPlaces} ${t('places')}, ${demoItems} ${t('items')})`,async()=>{let ids=new Set();state.places.filter(p=>p.demo).forEach(p=>descendants(p.id).forEach(id=>ids.add(id)));if(await change(s=>{s.places=s.places.filter(x=>!ids.has(x.id));s.items=s.items.filter(x=>!x.demo&&!ids.has(x.location));})){closeModal();render();}});break;}
 case 'reorder':reorderForm(id);break;case 'reorder-up':await reorder(id,-1);break;case 'reorder-down':await reorder(id,1);break;
}}
document.addEventListener('click',e=>{action(e).catch(()=>toast(t('storageError')));});$('#addButton').onclick=()=>current.page==='shopping'?shoppingForm():addMenu();$('#settingsButton').onclick=()=>location.hash='settings';
function route(){const [page,id]=(location.hash.slice(1)||'home').split('/');current={page:['home','places','items','search','favorites','settings','shopping','place','item'].includes(page)?page:'home',id};deep=false;render();window.scrollTo(0,0);if(page==='search'&&searchQuery){const input=$('#searchInput');input?.focus();input?.setSelectionRange?.(searchQuery.length,searchQuery.length);}}
window.addEventListener('hashchange',route);
$('#main').innerHTML=`<p>${t('loading')}</p>`;initStore().then(route);
